theorem PBBasic001 :
    {f : ℤ → ℤ | ∀ x y, f (2 * x) + 2 * f y = f (f (x + y))}
      = {0} ∪ {(fun x ↦ 2 * x + c)| (c : ℤ)}

theorem PBBasic003 :
    {f : ℝ → ℝ | ∀ a b, (b - a) * f (f a) = a * f (a + f b)}
      = {0} ∪ {(fun x ↦ - x + k) | (k : ℝ)}

theorem PBBasic004 :
    {g : ℝ → ℝ | StrictMono g ∧ g.Surjective ∧ ∀ x, g (g x) = g x + 20 * x}
      = {(fun x ↦ 5 * x)}
